{
  "name": "@devwellington/opencode-context-plugin",
  "version": "1.8.2",
  "description": "OpenCode plugin that saves session context to .opencode/context-session/ after compaction and session end",
  "main": "index.js",
  "type": "module",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "context",
    "session",
    "memory",
    "ai",
    "productivity"
  ],
  "author": "Wellington Ribeiro",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DevWellington/opencode-context-plugin.git"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.0"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "dependencies": {
    "@aws-sdk/client-s3": "^3.1053.0",
    "@google-cloud/storage": "^7.19.0",
    "gray-matter": "^4.0.3"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  },
  "scripts": {
    "test": "node --experimental-vm-modules node_modules/jest/bin/jest.js",
    "test:watch": "node --experimental-vm-modules node_modules/jest/bin/jest.js --watch",
    "test:coverage": "node --experimental-vm-modules node_modules/jest/bin/jest.js --coverage",
    "search": "node src/cli/search.js",
    "validate": "node scripts/validate-reports.js",
    "regenerate": "node scripts/regenerate-summaries.js",
    "postinstall": "node scripts/install-agents.js && node scripts/install-obsidian-plugin.js"
  },
  "bundledPlugins": {
    "show-hidden-files": "./.obsidian/plugins/show-hidden-files"
  },
  "bin": {
    "context-search": "src/cli/search.js",
    "ocp-agents": "scripts/ocp-agents.js"
  },
  "files": [
    "index.js",
    "src/",
    "agents/",
    "scripts/",
    "README.md",
    "CHANGELOG.md",
    "PUBLISH.md"
  ]
}

---
description: Generate annual context summary by aggregating monthly reports (reads monthly-*.md)
usage: '@ocp-generate-annual [year]'

import { generateAnnualSummary } from '@devwellington/opencode-context-plugin';

export default async function({ session, args }) {
  const directory = session.directory;
  const year = args[0] || new Date().getFullYear().toString();

  try {
    const result = await generateAnnualSummary(directory, year);
    return `✅ Annual summary generated!\n\n**Summary:**\n- Generated annual report\n[View file](${directory}/reports/annual-${year}.md)`;
  } catch (error) {
    return `❌ Error generating annual summary: ${error.message}`;
  }
}

---
description: Update intelligence-learning.md by reading all 4 report levels (daily, weekly, monthly, annual) and updating the project's intelligence base
usage: '@ocp-generate-intelligence-learning'

import { updateIntelligenceLearning } from '@devwellington/opencode-context-plugin';

export default async function({ session }) {
  const directory = session.directory;

  try {
    const result = await updateIntelligenceLearning(directory);
    const isSkipped = result.skipped;
    const summary = isSkipped
      ? `Skipped: ${result.reason || 'No new sessions to process'}`
      : `Updated with ${result.newSessions || 0} new sessions across ${result.entries || 0} entries`;
    return `✅ Intelligence learning updated!\n\n**Summary:**\n- ${summary}\n[View file](${directory}/intelligence-learning.md)`;
  } catch (error) {
    return `❌ Error updating intelligence learning: ${error.message}`;
  }
}

